def compute(vars):
    authorized_shares = vars["v2"]
    remaining_shares = vars["v1"]

    if authorized_shares == 0:
        return None

    ratio_percent = (remaining_shares / authorized_shares) * 100
    result = int(ratio_percent + 0.5)

    return {
        "value": result,
        "trace": {
            "remaining_shares": remaining_shares,
            "authorized_shares": authorized_shares,
            "ratio_percent": ratio_percent,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
